    public struct SyncRequest: Codable, Hashable, Sendable {
        public var cursor: Int
        public var ops: [Op]
        public var epoch: Int
        public var reset: Bool?
        public var scope: String

        public init(cursor: Int, ops: [Op] = [], epoch: Int = 0, reset: Bool? = nil, scope: String = "") {
            self.cursor = cursor
            self.ops = ops
            self.epoch = epoch
            self.reset = reset
            self.scope = scope
        }

        enum CodingKeys: String, CodingKey {
            case cursor = "cursor"
            case ops = "ops"
            case epoch = "epoch"
            case reset = "reset"
            case scope = "scope"
        }

        public init(from decoder: Decoder) throws {
            let container = try decoder.container(keyedBy: CodingKeys.self)
            cursor = try container.decode(Int.self, forKey: .cursor)
            ops = try container.decode([Op].self, forKey: .ops)
            epoch = try container.decodeAbsent(Int.self, forKey: .epoch) ?? 0
            reset = try container.decodeAbsent(Bool.self, forKey: .reset)
            scope = try container.decodeAbsent(String.self, forKey: .scope) ?? ""
            if decoder.validates {
                do {
                    let value = self.cursor
                    try check(value >= 0, .cursor, in: container, "cursor at least 0")
                }
                do {
                    let value = self.epoch
                    try check(value >= 0, .epoch, in: container, "epoch at least 0")
                }
            }
        }

        public func encode(to encoder: Encoder) throws {
            var container = encoder.container(keyedBy: CodingKeys.self)
            try container.encode(self.cursor, forKey: .cursor)
            try container.encode(self.ops, forKey: .ops)
            try container.encode(self.epoch, forKey: .epoch)
            try container.encodeIfPresent(self.reset, forKey: .reset)
            try container.encode(self.scope, forKey: .scope)
        }
    }

    public enum SyncResponse: Codable, Hashable, Sendable {
        case changes(SyncResponseChanges)
        case snapshot(SyncResponseSnapshot)

        public init(from decoder: Decoder) throws {
            if let value = try? SyncResponseChanges(from: decoder) {
                self = .changes(value)
                return
            }
            if let value = try? SyncResponseSnapshot(from: decoder) {
                self = .snapshot(value)
                return
            }
